// ot_w5_power_ctl -- stage power-gating controller of the V4.1 ROM layer die (W18).
//
// One controller per gated power domain.  It lives in the die's ALWAYS-ON island (the hub's VM column,
// W10 re-fit) and drives the domain's header-switch rings (tools/w18/die_pdn.py switch_ring), its output
// isolation, its reset and its clock enable.  The domain is split into NSUB sub-domains (switch-ring
// segments) that are enabled one after another, ``cfg_step`` cycles apart and only after the previous
// segment's ring has acknowledged (the ack is the last header cell of the ring's enable daisy chain), which
// bounds the rush current: the W14 model's staggered wake is ~100 ten-cycle sub-domains in 1 us
// (ReGate 10-cycle domains), i.e. NSUB = 100, cfg_step = 10 at 1.087 GHz.
//
// Power-up   : OFF -> (req_on) UP: sw_en[i] rises in order, each >= cfg_step cycles after the previous and
//              after sw_ack[i-1] -> all acks -> RST: domain reset held cfg_rst cycles with its clock enabled
//              (synchronous reset needs edges) -> ISO release -> ON (pwr_good).
// Power-down : ON -> (!req_on) clock off -> isolate -> assert reset -> all switches off at once (turn-off
//              draws no rush current) -> all acks low -> OFF.
// A request that changes mid-sequence completes the sequence in progress first.
// An ack that does not arrive within cfg_ack_to cycles (a dead ring segment) latches ``fault`` and holds
// the domain isolated and in reset; only rst_n clears it.
module ot_w5_power_ctl #(
    parameter int NSUB = 100,
    parameter int CW   = 16
) (
    input  logic            clk,        // always-on clock
    input  logic            rst_n,      // always-on reset
    input  logic            req_on,     // level: the schedule wants the domain powered
    input  logic [CW-1:0]   cfg_step,   // cycles between consecutive segment enables (>= 1)
    input  logic [7:0]      cfg_rst,    // domain reset cycles after the last ack (>= 1)
    input  logic [CW-1:0]   cfg_ack_to, // ack timeout, cycles
    (* keep, dont_touch *) output logic [NSUB-1:0] sw_en,      // header ring segment enables (1 = switches on)
    input  logic [NSUB-1:0] sw_ack,     // ring segment acknowledges (daisy-chain tail)
    (* keep, dont_touch *) output logic            iso_n,      // 0 = domain outputs clamped
    (* keep, dont_touch *) output logic            dom_rst_n,  // domain reset
    (* keep, dont_touch *) output logic            clk_en,     // domain clock enable (to the domain's root ICG)
    (* keep, dont_touch *) output logic            pwr_good,   // domain usable
    (* keep, dont_touch *) output logic            fault,
    output wire [3+((NSUB>1)?$clog2(NSUB+1):1)+CW+NSUB+5-1:0] snapshot
);
    typedef enum logic [2:0] {S_OFF, S_UP, S_RST, S_ISO, S_ON, S_DN_CLK, S_DN_ISO, S_DN_SW} st_t;
    (* keep, dont_touch *) st_t st;
    localparam int IW = (NSUB > 1) ? $clog2(NSUB + 1) : 1;
    (* keep, dont_touch *) logic [IW-1:0] idx;          // next segment to enable
    (* keep, dont_touch *) logic [CW-1:0] cnt;
    (* keep, dont_touch *) logic          all_ack, none_ack;
    assign all_ack  = &sw_ack;
    assign none_ack = ~|sw_ack;

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            st <= S_OFF; idx <= '0; cnt <= '0; sw_en <= '0;
            iso_n <= 1'b0; dom_rst_n <= 1'b0; clk_en <= 1'b0; pwr_good <= 1'b0; fault <= 1'b0;
        end else if (fault) begin
            iso_n <= 1'b0; dom_rst_n <= 1'b0; clk_en <= 1'b0; pwr_good <= 1'b0;
        end else begin
            case (st)
                S_OFF: if (req_on && none_ack) begin
                    st <= S_UP; idx <= '0; cnt <= cfg_step;   // first segment enables immediately
                end
                S_UP: begin
                    // enable segment idx once the spacing has elapsed and the previous segment has acked
                    if (idx == IW'(NSUB)) begin
                        if (all_ack) begin st <= S_RST; cnt <= CW'(cfg_rst); clk_en <= 1'b1; end
                        else if (cnt >= cfg_ack_to) fault <= 1'b1;
                        else cnt <= cnt + 1'b1;
                    end else if (cnt >= cfg_step && (idx == '0 || sw_ack[idx - 1'b1])) begin
                        sw_en[idx] <= 1'b1; idx <= idx + 1'b1; cnt <= 1;
                    end else if (idx != '0 && !sw_ack[idx - 1'b1] && cnt >= cfg_ack_to) begin
                        fault <= 1'b1;
                    end else cnt <= cnt + 1'b1;
                end
                S_RST: if (cnt <= 1) begin dom_rst_n <= 1'b1; st <= S_ISO; end
                       else cnt <= cnt - 1'b1;
                S_ISO: begin iso_n <= 1'b1; pwr_good <= 1'b1; st <= S_ON; end
                S_ON: if (!req_on) begin pwr_good <= 1'b0; clk_en <= 1'b0; st <= S_DN_CLK; end
                S_DN_CLK: begin iso_n <= 1'b0; st <= S_DN_ISO; end
                S_DN_ISO: begin dom_rst_n <= 1'b0; sw_en <= '0; cnt <= '0; st <= S_DN_SW; end
                S_DN_SW: if (none_ack) st <= S_OFF;
                         else if (cnt >= cfg_ack_to) fault <= 1'b1;
                         else cnt <= cnt + 1'b1;
                default: st <= S_OFF;
            endcase
        end
    end
assign snapshot = {st,idx,cnt,sw_en,iso_n,dom_rst_n,clk_en,pwr_good,fault};
endmodule

`timescale 1ns/1ps
// ---------------------------------------------------------------------------
// ot_w5_sched -- static-schedule pre-wake for one power-gated ROM stage domain (always-on island).
//
// One per gated domain (a die region of many elements share it; the single-element vehicle instantiates one).
// The stage's static token schedule is known: whenever the hub issues a token to the stage it also announces
// the number of cycles until the NEXT arrival (`sched_v`, `sched_gap`; AR batch 1: the token period; MTP / the
// wavefront: the position spacing).  The countdown requests power `lead + bet` cycles before that arrival
// (`lead` >= switch-ring wake + domain reset + retention restore; `bet` = break-even margin) and releases it
// once the domain has been idle `idle_min` consecutive cycles and the next arrival is farther than that.
//
// The power sequence itself (staggered header-ring enable, reset, isolation release, power-down order, dead
// ring fault) is the W18 controller ot_w5_power_ctl, instantiated unchanged.
//
// pg_en = 0 holds the domain powered (req_on = 1): gating is opt-in at run time as well as by parameter.
// ---------------------------------------------------------------------------
module ot_w5_sched #(
    parameter integer NSUB = 4,           // header-ring segments of the domain
    parameter integer TW   = 24           // schedule counter width (AR period at 1.2 GHz is ~486k cycles)
) (
    input  wire            clk,           // always-on clock
    input  wire            rst_n,         // always-on reset
    input  wire            pg_en,
    input  wire            sched_v,       // the hub announces the next arrival
    input  wire [TW-1:0]   sched_gap,     // cycles from now until that arrival
    input  wire [TW-1:0]   cfg_lead,      // wake lead: ring wake + reset + restore
    input  wire [TW-1:0]   cfg_bet,       // break-even margin: never sleep for a shorter gap
    input  wire [7:0]      cfg_idle,      // idle cycles before the domain may sleep (>= the element drain)
    input  wire [15:0]     cfg_step,
    input  wire [7:0]      cfg_rst,
    input  wire [15:0]     cfg_ack_to,
    input  wire            dom_busy,      // the domain has work in flight (element busy, partials, restore)
    output wire [NSUB-1:0] sw_en,
    input  wire [NSUB-1:0] sw_ack,
    output wire            iso_n,
    output wire            dom_rst_n,
    output wire            clk_en,
    output wire            pwr_good,
    output wire            fault,
    output wire            req_on,
    output wire [2*TW+10+3+((NSUB>1)?$clog2(NSUB+1):1)+16+NSUB+5-1:0] snapshot
);
    wire [3+((NSUB>1)?$clog2(NSUB+1):1)+16+NSUB+5-1:0] pg_snapshot;
    reg [TW-1:0] cnt;
    (* keep, dont_touch *) reg          cnt_v;
    (* keep, dont_touch *) reg [7:0]    idle;
    always @(posedge clk or negedge rst_n)
        if (!rst_n) begin cnt <= {TW{1'b0}}; cnt_v <= 1'b0; idle <= 8'd0; end
        else begin
            if (sched_v) begin cnt <= sched_gap; cnt_v <= 1'b1; end
            else if (cnt_v && cnt != {TW{1'b0}}) cnt <= cnt - 1'b1;
            else cnt_v <= 1'b0;                               // the announced arrival has passed
            if (dom_busy) idle <= 8'd0;
            else if (idle != 8'hff) idle <= idle + 8'd1;
        end
    (* keep, dont_touch *) reg  [TW:0] th;                                           // lead + bet, registered (static configuration)
    always @(posedge clk or negedge rst_n)
        if (!rst_n) th <= {(TW+1){1'b0}};
        else th <= {1'b0, cfg_lead} + {1'b0, cfg_bet};
    wire        near = cnt_v && ({1'b0, cnt} <= th);
    wire        idle_long = !dom_busy && idle >= cfg_idle;
    assign req_on = !pg_en || !idle_long || near;

    ot_w5_power_ctl #(.NSUB(NSUB), .CW(16)) u_pg (
        .snapshot(pg_snapshot), .clk(clk), .rst_n(rst_n), .req_on(req_on), .cfg_step(cfg_step), .cfg_rst(cfg_rst),
        .cfg_ack_to(cfg_ack_to), .sw_en(sw_en), .sw_ack(sw_ack), .iso_n(iso_n), .dom_rst_n(dom_rst_n),
        .clk_en(clk_en), .pwr_good(pwr_good), .fault(fault));
assign snapshot = {cnt,cnt_v,idle,th,pg_snapshot};
endmodule

module ot_w5_stage_pg_ctl_sp #(
    parameter integer NSUB = 4,
    parameter integer TW = 24
) (
    input  wire         clk,           // stage spine root
    input  wire         a_clk,         // always-on branch
    input  wire         rst_n,
    input  wire         pg_en,
    input  wire         sched_v,
    input  wire [TW-1:0] sched_gap,
    input  wire [TW-1:0] pg_lead,
    input  wire [TW-1:0] pg_bet,
    input  wire [7:0]   pg_idle,
    input  wire [15:0]  pg_step,
    input  wire [7:0]   pg_rst,
    input  wire [15:0]  pg_ack_to,
    input  wire         go,
    input  wire         dom_busy,
    input  wire         all_ready,
    output wire [NSUB-1:0] sw_en,
    input  wire [NSUB-1:0] sw_ack,
    output wire         s_clk,
    output wire         iso_n,
    output wire         dom_rst_n,
    output wire         pwr_good,
    (* keep, dont_touch *) output reg          late,
    output wire         ctl_fault,
    output wire [2*TW+12+3+((NSUB>1)?$clog2(NSUB+1):1)+16+NSUB+5-1:0] snapshot
);
    wire [2*TW+10+3+((NSUB>1)?$clog2(NSUB+1):1)+16+NSUB+5-1:0] sched_snapshot;
    wire clk_en, req_on;
    ot_w5_sched #(.NSUB(NSUB), .TW(TW)) u_sched (
        .snapshot(sched_snapshot), .clk(a_clk), .rst_n(rst_n), .pg_en(pg_en), .sched_v(sched_v), .sched_gap(sched_gap), .cfg_lead(pg_lead),
        .cfg_bet(pg_bet), .cfg_idle(pg_idle), .cfg_step(pg_step), .cfg_rst(pg_rst), .cfg_ack_to(pg_ack_to),
        .dom_busy(go | dom_busy), .sw_en(sw_en), .sw_ack(sw_ack), .iso_n(iso_n), .dom_rst_n(dom_rst_n),
        .clk_en(clk_en), .pwr_good(pwr_good), .fault(ctl_fault), .req_on(req_on));
    // spine: on while a ring segment is powered and the ring is not being switched off
    (* keep, dont_touch *) reg spine_on;
    always @(posedge a_clk or negedge rst_n)
        if (!rst_n) spine_on <= 1'b0;
`ifdef PG_MUTANT_SPINE_LATE
        else spine_on <= pwr_good;
`else
        else spine_on <= (|sw_en) & (|sw_ack);
`endif
    ot_hdc_cg u_spine_cg (.clk(clk), .en(spine_on | !rst_n), .gclk(s_clk));
    always @(posedge a_clk or negedge rst_n)
        if (!rst_n) late <= 1'b0;
        else if (go && !all_ready) late <= 1'b1;
assign snapshot={spine_on,late,sched_snapshot};
endmodule
module ot_w5_stage_pg_ao_cdc #(
    parameter integer RETENTION_EDGE_WRITE = 0,
    parameter integer K = 1,
    parameter integer NSEG = 8,
    parameter integer NB = 2,
    parameter integer NSUB = 4,
    parameter integer TW = 24
) (
    input  wire         clk,
    input  wire         aon_clk,
    input  wire         rst_n,
    input  wire [K-1:0] cfg_v,
    input  wire [4:0]   cfg_a,
    input  wire [47:0]  cfg_d,
    input  wire         go,
