assign rp_d=rp_d_p; // immutable replay tuple under quarantine
assign ready_a=ready_a_p & {$bits(ready_a){!quarantine}};
assign pv=pv_p & {$bits(pv){!quarantine}};
assign pval=pval_p & {$bits(pval){!quarantine}};
assign prow=prow_p & {$bits(prow){!quarantine}};
